 1→<?php
 2→
 3→namespace App\Http\Controllers;
 4→
 5→use App\Models\SubExploitation;
 6→use Inertia\Inertia;
 7→use Inertia\Response;
 8→
 9→class SubExploitationController extends Controller
10→{
11→    public function show(SubExploitation $subExploitation): Response
12→    {
13→        $subExploitation->load(['exploitation', 'animals']);
14→
15→        $animalsCount = $subExploitation->animals->count();
16→        $capacityRatio = $subExploitation->max_capacity > 0
17→            ? $subExploitation->current_capacity / $subExploitation->max_capacity
18→            : 0;
19→
20→        // Mocked semáforo indicators
21→        $capacityStatus = $capacityRatio > 0.8 ? 'danger' : ($capacityRatio > 0.6 ? 'warning' : 'ok');
22→        $alertsCount = rand(0, 3);
23→        $pendingCount = rand(0, 5);
24→
25→        return Inertia::render('subexplotaciones/show', [
26→            'subExploitation' => $subExploitation,
27→            'animalsCount' => $animalsCount,
28→            'semaforo' => [
29→                'capacity' => $capacityStatus,
30→                'alerts' => $alertsCount,
31→                'pending' => $pendingCount,
32→            ],
33→        ]);
34→    }
35→}
36→

  1→import { Head, Link } from '@inertiajs/react';
  2→import { Baby, CheckCircle2, List, FileText, ScanLine, Syringe, Timer, TriangleAlert } from 'lucide-react';
  3→import { index as animalesIndex } from '@/actions/App/Http/Controllers/AnimalController';
  4→import { show as subExploitationShow } from '@/actions/App/Http/Controllers/SubExploitationController';
  5→import AppLayout from '@/layouts/app-layout';
  6→import { dashboard } from '@/routes';
  7→import type { BreadcrumbItem } from '@/types';
  8→
  9→type SubExploitation = {
 10→    id: number;
 11→    species: string;
 12→    exploitation_type: string;
 13→    zootechnical_classification: string;
 14→    productive_system: string;
 15→    current_capacity: number;
 16→    max_capacity: number;
 17→    sustainability: string | null;
 18→    self_consumption: boolean;
 19→    census_date: string | null;
 20→    status: string | null;
 21→};
 22→
 23→type Semaforo = {
 24→    capacity: 'ok' | 'warning' | 'danger';
 25→    alerts: number;
 26→    pending: number;
 27→};
 28→
 29→type Props = {
 30→    subExploitation: SubExploitation;
 31→    animalsCount: number;
 32→    semaforo: Semaforo;
 33→};
 34→
 35→const speciesLabels: Record<string, string> = {
 36→    bovine: 'Bovino',
 37→    ovine: 'Ovino',
 38→    caprine: 'Caprino',
 39→    porcine: 'Porcino',
 40→    equine: 'Equino',
 41→};
 42→
 43→const speciesHeaderColors: Record<string, string> = {
 44→    bovine: 'bg-[#E53935]',
 45→    ovine: 'bg-black',
 46→    caprine: 'bg-black',
 47→    porcine: 'bg-neutral-700',
 48→    equine: 'bg-amber-900',
 49→};
 50→
 51→function getCapacityGroup(maxCapacity: number): string {
 52→    if (maxCapacity <= 10) return 'Grupo I (1-10 UGM)';
 53→    if (maxCapacity <= 40) return 'Grupo II (11-40 UGM)';
 54→    if (maxCapacity <= 100) return 'Grupo III (41-100 UGM)';
 55→    return 'Grupo IV (>100 UGM)';
 56→}
 57→
 58→function SemaforoIndicator({ status, alerts, pending }: Semaforo) {
 59→    const capacityConfig = {
 60→        ok: { bg: 'bg-[#2E7D32]', text: 'text-white', icon: CheckCircle2, label: 'Capacidad' },
 61→        warning: { bg: 'bg-[#F9A825]', text: 'text-black', icon: TriangleAlert, label: 'Capacidad' },
 62→        danger: { bg: 'bg-[#E53935]', text: 'text-white', icon: Timer, label: 'Capacidad' },
 63→    };
 64→
 65→    const cap = capacityConfig[status];
 66→    const CapIcon = cap.icon;
 67→
 68→    return (
 69→        <div className="flex gap-2">
 70→            <div className={`flex flex-1 flex-col items-center gap-1 rounded-sm ${cap.bg} px-3 py-3`}>
 71→                <CapIcon className={`size-5 ${cap.text}`} />
 72→                <span className={`text-[11px] font-semibold ${cap.text}`}>{cap.label}</span>
 73→            </div>
 74→            <div className="flex flex-1 flex-col items-center gap-1 rounded-sm bg-[#F9A825] px-3 py-3">
 75→                <TriangleAlert className="size-5 text-black" />
 76→                <span className="text-[11px] font-semibold text-black">
 77→                    {alerts} {alerts === 1 ? 'Alerta' : 'Alertas'}
 78→                </span>
 79→            </div>
 80→            <div className="flex flex-1 flex-col items-center gap-1 rounded-sm bg-[#E53935] px-3 py-3">
 81→                <Timer className="size-5 text-white" />
 82→                <span className="text-[11px] font-semibold text-white">
 83→                    {pending} {pending === 1 ? 'Pendiente' : 'Pendientes'}
 84→                </span>
 85→            </div>
 86→        </div>
 87→    );
 88→}
 89→
 90→function DetailRow({ label, value, valueColor }: { label: string; value: string; valueColor?: string }) {
 91→    return (
 92→        <div className="flex items-center justify-between px-4 py-3.5">
 93→            <span className="text-[13px] font-medium text-[#757575]">{label}</span>
 94→            <span className={`text-[13px] font-bold ${valueColor ?? 'text-black'}`}>{value}</span>
 95→        </div>
 96→    );
 97→}
 98→
 99→function DetailRowWithSub({ label, value, sub }: { label: string; value: string; sub: string }) {
100→    return (
101→        <div className="flex items-center justify-between px-4 py-3.5">
102→            <span className="text-[13px] font-medium text-[#757575]">{label}</span>
103→            <div className="flex flex-col items-end gap-0.5">
104→                <span className="text-[13px] font-bold text-black">{value}</span>
105→                <span className="text-[11px] font-medium text-[#BDBDBD]">{sub}</span>
106→            </div>
107→        </div>
108→    );
109→}
110→
111→function ActionButton({ icon: Icon, label, href }: { icon: React.ComponentType<{ className?: string }>; label: string; href?: string }) {
112→    const content = (
113→        <div className="flex flex-1 flex-col items-center gap-2 border-2 border-black p-4">
114→            <Icon className="size-6 text-[#E53935]" />
115→            <span className="text-center text-[13px] font-semibold">{label}</span>
116→        </div>
117→    );
118→
119→    if (href) {
120→        return <Link href={href} className="flex flex-1">{content}</Link>;
121→    }
122→
123→    return <button className="flex flex-1 cursor-default opacity-50">{content}</button>;
124→}
125→
126→export default function SubExploitationShow({ subExploitation, animalsCount, semaforo }: Props) {
127→    const breadcrumbs: BreadcrumbItem[] = [
128→        { title: 'Mi Explotación', href: dashboard() },
129→        {
130→            title: `${speciesLabels[subExploitation.species] ?? subExploitation.species} · ${subExploitation.zootechnical_classification}`,
131→            href: subExploitationShow.url(subExploitation.id),
132→        },
133→    ];
134→
135→    const label = speciesLabels[subExploitation.species] ?? subExploitation.species;
136→    const headerColor = speciesHeaderColors[subExploitation.species] ?? 'bg-black';
137→    const sustainabilityColor = subExploitation.sustainability?.toLowerCase() === 'ecológico' ? 'text-[#2E7D32]' : undefined;
138→    const censusDate = subExploitation.census_date
139→        ? new Date(subExploitation.census_date).toLocaleDateString('es-ES', { day: '2-digit', month: '2-digit', year: 'numeric' })
140→        : null;
141→
142→    return (
143→        <AppLayout breadcrumbs={breadcrumbs}>
144→            <Head title={`${label} · ${subExploitation.zootechnical_classification}`} />
145→            <div className="flex flex-col gap-5 p-6">
146→                {/* Species Header Card */}
147→                <div className={`${headerColor} rounded-lg px-4 py-4 text-white`}>
148→                    <p className="text-lg font-bold">
149→                        {label} · {subExploitation.exploitation_type}
150→                    </p>
151→                    <p className="text-[13px] font-medium opacity-85">
152→                        {subExploitation.zootechnical_classification} · {subExploitation.productive_system}
153→                    </p>
154→                </div>
155→
156→                {/* Semáforo */}
157→                <SemaforoIndicator
158→                    status={semaforo.capacity}
159→                    alerts={semaforo.alerts}
160→                    pending={semaforo.pending}
161→                />
162→
163→                {/* Datos Zootécnicos */}
164→                <div className="overflow-hidden border-2 border-black">
165→                    <DetailRow
166→                        label="Clasificación zootécnica"
167→                        value={subExploitation.zootechnical_classification}
168→                    />
169→                    <div className="h-[2px] bg-black" />
170→                    <DetailRow
171→                        label="Capacidad productiva"
172→                        value={getCapacityGroup(subExploitation.max_capacity)}
173→                    />
174→                    <div className="h-[2px] bg-black" />
175→                    <DetailRow
176→                        label="Forma de cría"
177→                        value={subExploitation.sustainability ?? 'Convencional'}
178→                        valueColor={sustainabilityColor}
179→                    />
180→                    <div className="h-[2px] bg-black" />
181→                    <DetailRowWithSub
182→                        label="Censo actual"
183→                        value={`${animalsCount} animales`}
184→                        sub={censusDate ? `Actualizado: ${censusDate}` : ''}
185→                    />
186→                </div>
187→
188→                {/* Acciones Rápidas */}
189→                <div className="flex flex-col gap-3">
190→                    <span className="text-xs font-semibold tracking-[2px] text-[#757575]">
191→                        ACCIONES RÁPIDAS
192→                    </span>
193→                    <div className="flex gap-3">
194→                        <ActionButton icon={List} label="Ver animales" href={animalesIndex.url(subExploitation.id)} />
195→                        <ActionButton icon={FileText} label="Trámites" href="/normativa" />
196→                        <ActionButton icon={Syringe} label="Campañas" href="/normativa" />
197→                    </div>
198→                </div>
199→
200→                {/* CTA Buttons */}
201→                <Link
202→                    href="/nacimientos/crear"
203→                    className="flex items-center justify-center gap-2 bg-[#2E7D32] px-4 py-4 text-white"
204→                >
205→                    <Baby className="size-5" />
206→                    <span className="text-[15px] font-bold">Informar nacimiento</span>
207→                </Link>
208→
209→                <Link
210→                    href="/scanner"
211→                    className="flex items-center justify-center gap-2 bg-black px-4 py-4 text-white"
212→                >
213→                    <ScanLine className="size-5" />
214→                    <span className="text-[15px] font-bold">Escanear crotal (OCR)</span>
215→                </Link>
216→            </div>
217→        </AppLayout>
218→    );
219→}
