  1→import { Head, Link, router } from '@inertiajs/react';
  2→import { ArrowLeft, ChevronRight, ScanLine, Search } from 'lucide-react';
  3→import { useState, useMemo } from 'react';
  4→import { index as animalesIndex, show as animalShow } from '@/actions/App/Http/Controllers/AnimalController';
  5→import { show as subExploitationShow } from '@/actions/App/Http/Controllers/SubExploitationController';
  6→import AppLayout from '@/layouts/app-layout';
  7→import type { BreadcrumbItem } from '@/types';
  8→
  9→type Animal = {
 10→    id: number;
 11→    crotal_code: string;
 12→    status: 'ok' | 'warning' | 'danger';
 13→    has_alert: boolean;
 14→    is_immobilized: boolean;
 15→    subtitle: string;
 16→    subtitle_color: 'danger' | 'muted';
 17→};
 18→
 19→type SubExploitation = {
 20→    id: number;
 21→    species: string;
 22→    zootechnical_classification: string;
 23→};
 24→
 25→type Props = {
 26→    subExploitation: SubExploitation;
 27→    animals: Animal[];
 28→    speciesLabel: string;
 29→};
 30→
 31→const speciesLabels: Record<string, string> = {
 32→    bovine: 'Bovino',
 33→    ovine: 'Ovino',
 34→    caprine: 'Caprino',
 35→    porcine: 'Porcino',
 36→    equine: 'Equino',
 37→};
 38→
 39→type Filter = 'todos' | 'alertas' | 'inmovilizados';
 40→
 41→const statusColors: Record<string, string> = {
 42→    ok: 'bg-[#2E7D32]',
 43→    warning: 'bg-[#F9A825]',
 44→    danger: 'bg-[#E53935]',
 45→};
 46→
 47→export default function AnimalesIndex({ subExploitation, animals, speciesLabel }: Props) {
 48→    const [search, setSearch] = useState('');
 49→    const [filter, setFilter] = useState<Filter>('todos');
 50→
 51→    const filteredAnimals = useMemo(() => {
 52→        let result = animals;
 53→
 54→        if (search.trim()) {
 55→            const query = search.trim().toUpperCase();
 56→            result = result.filter((a) => a.crotal_code.includes(query));
 57→        }
 58→
 59→        if (filter === 'alertas') {
 60→            result = result.filter((a) => a.has_alert);
 61→        } else if (filter === 'inmovilizados') {
 62→            result = result.filter((a) => a.is_immobilized);
 63→        }
 64→
 65→        return result;
 66→    }, [animals, search, filter]);
 67→
 68→    const alertCount = animals.filter((a) => a.has_alert).length;
 69→    const immobilizedCount = animals.filter((a) => a.is_immobilized).length;
 70→
 71→    const label = speciesLabels[subExploitation.species] ?? subExploitation.species;
 72→
 73→    const breadcrumbs: BreadcrumbItem[] = [
 74→        { title: 'Mi Explotación', href: '/dashboard' },
 75→        {
 76→            title: `${label} · ${subExploitation.zootechnical_classification}`,
 77→            href: subExploitationShow.url(subExploitation.id),
 78→        },
 79→        { title: 'Animales', href: animalesIndex.url(subExploitation.id) },
 80→    ];
 81→
 82→    return (
 83→        <AppLayout breadcrumbs={breadcrumbs}>
 84→            <Head title="Animales" />
 85→            <div className="flex flex-col gap-4 p-6">
 86→                {/* Header */}
 87→                <div className="flex items-center gap-2">
 88→                    <Link href={subExploitationShow.url(subExploitation.id)}>
 89→                        <ArrowLeft className="size-6 text-black" />
 90→                    </Link>
 91→                    <h1 className="text-lg font-bold text-black">Animales</h1>
 92→                </div>
 93→
 94→                {/* Search Bar */}
 95→                <div className="flex items-center gap-3.5 bg-[#F5F5F5] px-4 py-3.5">
 96→                    <Search className="size-5 text-[#757575]" />
 97→                    <input
 98→                        type="text"
 99→                        placeholder="Buscar por nº de crotal..."
100→                        value={search}
101→                        onChange={(e) => setSearch(e.target.value)}
102→                        className="flex-1 bg-transparent text-[15px] text-black placeholder-[#BDBDBD] outline-none"
103→                    />
104→                </div>
105→
106→                {/* Filter Chips */}
107→                <div className="flex gap-2">
108→                    <FilterChip
109→                        label={`Todos (${animals.length})`}
110→                        active={filter === 'todos'}
111→                        onClick={() => setFilter('todos')}
112→                    />
113→                    <FilterChip
114→                        label="Con alertas"
115→                        active={filter === 'alertas'}
116→                        onClick={() => setFilter('alertas')}
117→                    />
118→                    <FilterChip
119→                        label="Inmovilizados"
120→                        active={filter === 'inmovilizados'}
121→                        onClick={() => setFilter('inmovilizados')}
122→                    />
123→                </div>
124→
125→                {/* Count Row */}
126→                <div className="flex items-center justify-between">
127→                    <span className="text-2xl font-bold text-black">{filteredAnimals.length} animales</span>
128→                    <span className="text-sm font-medium text-[#757575]">{speciesLabel}</span>
129→                </div>
130→
131→                {/* Animal List */}
132→                <div className="overflow-hidden border-2 border-black">
133→                    {filteredAnimals.map((animal, idx) => (
134→                        <div key={animal.id}>
135→                            {idx > 0 && <div className="h-[2px] bg-black" />}
136→                            <Link
137→                                href={animalShow.url({ subExploitation: subExploitation.id, animal: animal.id })}
138→                                className="flex items-center gap-3 p-4"
139→                            >
140→                                <div className={`size-3 shrink-0 rounded-full ${statusColors[animal.status]}`} />
141→                                <div className="flex min-w-0 flex-1 flex-col gap-0.5">
142→                                    <span className="text-[15px] font-bold text-black">{animal.crotal_code}</span>
143→                                    <span
144→                                        className={`text-xs font-medium ${
145→                                            animal.subtitle_color === 'danger' ? 'text-[#E53935]' : 'text-[#757575]'
146→                                        }`}
147→                                    >
148→                                        {animal.subtitle}
149→                                    </span>
150→                                </div>
151→                                {animal.has_alert && (
152→                                    <span className="shrink-0 bg-[#F9A825] px-2 py-1 text-[10px] font-bold text-black">
153→                                        Alerta
154→                                    </span>
155→                                )}
156→                                <ChevronRight className="size-5 shrink-0 text-[#757575]" />
157→                            </Link>
158→                        </div>
159→                    ))}
160→                    {filteredAnimals.length === 0 && (
161→                        <div className="px-4 py-8 text-center text-sm text-[#757575]">
162→                            No se encontraron animales
163→                        </div>
