 47→export default function AnimalesIndex({ subExploitation, animals, speciesLabel }: Props) {
 48→    const [search, setSearch] = useState('');
 49→    const [filter, setFilter] = useState<Filter>('todos');
 50→
 51→    const filteredAnimals = useMemo(() => {
 52→        let result = animals;
 53→
 54→        if (search.trim()) {
 55→            const query = search.trim().toUpperCase();
 56→            result = result.filter((a) => a.crotal_code.includes(query));
 57→        }
 58→
 59→        if (filter === 'alertas') {
 60→            result = result.filter((a) => a.has_alert);
 61→        } else if (filter === 'inmovilizados') {
 62→            result = result.filter((a) => a.is_immobilized);
 63→        }
 64→
 65→        return result;
 66→    }, [animals, search, filter]);
 67→
 68→    const alertCount = animals.filter((a) => a.has_alert).length;
 69→    const immobilizedCount = animals.filter((a) => a.is_immobilized).length;
 70→
 71→    const label = speciesLabels[subExploitation.species] ?? subExploitation.species;
