import { queryParams, type RouteQueryOptions, type RouteDefinition, type RouteFormDefinition, applyUrlDefaults } from './../../../../wayfinder'
/**
* @see \App\Http\Controllers\AnimalController::index
* @see app/Http/Controllers/AnimalController.php:13
* @route '/subexplotaciones/{subExploitation}/animales'
*/
export const index = (args: { subExploitation: number | { id: number } } | [subExploitation: number | { id: number } ] | number | { id: number }, options?: RouteQueryOptions): RouteDefinition<'get'> => ({
    url: index.url(args, options),
    method: 'get',
})

index.definition = {
    methods: ["get","head"],
    url: '/subexplotaciones/{subExploitation}/animales',
} satisfies RouteDefinition<["get","head"]>

/**
* @see \App\Http\Controllers\AnimalController::index
* @see app/Http/Controllers/AnimalController.php:13
* @route '/subexplotaciones/{subExploitation}/animales'
*/
index.url = (args: { subExploitation: number | { id: number } } | [subExploitation: number | { id: number } ] | number | { id: number }, options?: RouteQueryOptions) => {
    if (typeof args === 'string' || typeof args === 'number') {
        args = { subExploitation: args }
    }

    if (typeof args === 'object' && !Array.isArray(args) && 'id' in args) {
        args = { subExploitation: args.id }
    }

    if (Array.isArray(args)) {
        args = {
            subExploitation: args[0],
        }
    }

    args = applyUrlDefaults(args)

    const parsedArgs = {
        subExploitation: typeof args.subExploitation === 'object'
        ? args.subExploitation.id
        : args.subExploitation,
    }

    return index.definition.url
            .replace('{subExploitation}', parsedArgs.subExploitation.toString())
            .replace(/\/+$/, '') + queryParams(options)
}

/**
